<script setup>
import {computed} from 'vue';
import {cabinetCompartments} from '../shared/cabinet-compartments.mjs';
const props=defineProps({item:{type:Object,required:true}});
const layout=computed(()=>cabinetCompartments(props.item));
</script>
<template><section aria-label="Applied cabinet compartments"><h3>Applied compartments</h3><p data-testid="cabinet-compartment-summary">{{ layout.columns }} columns · {{ item.shelves }} shelves per column · {{ layout.columns*(item.shelves+1) }} compartments</p><p class="hint">Equal clear widths {{ (layout.bayWidth*1000).toFixed(1) }} mm. Cabinet shelves sets shelves per column. Diagram shows applied geometry with fronts hidden; both external doors stay unchanged. Apply cabinet to update.</p><svg role="img" aria-label="Cabinet compartment elevation" :viewBox="`${-item.width/2} 0 ${item.width} ${item.height}`" style="width:100%;height:180px;background:#e9eee7"><rect :x="-item.width/2" y="0" :width="item.width" :height="item.height" fill="#b88c59"/><rect v-for="(bay,i) in layout.bays" :key="i" :x="bay.x-bay.width/2" :y="item.thickness" :width="bay.width" :height="item.height-2*item.thickness" fill="#f4f1e9"/><g v-for="(bay,i) in layout.bays" :key="'s'+i"><rect v-for="n in item.shelves" :key="n" :x="bay.x-bay.width/2" :y="item.height-(item.thickness+(item.height-2*item.thickness)*n/(item.shelves+1))-item.thickness/2" :width="bay.width" :height="item.thickness" fill="#b88c59"/></g></svg></section></template>
